#[test]
fn builtin_policies_agree() {
    let ports = k::default_policies();
    assert_eq!(ports.len(), u::DEFAULT_POLICIES.len());
    for ((uname, up), (name, port)) in u::DEFAULT_POLICIES.iter().zip(&ports) {
        assert_eq!(uname.as_bytes(), name);
        assert_eq!(
            serde_json::to_value(&up.id).unwrap(),
            serde_json::json!(String::from_utf8(port.id.clone()).unwrap())
        );
        assert_eq!(up.version.as_bytes(), port.version);
        assert_eq!(up.statements.len(), port.statements.len());
        for (s, t) in up.statements.iter().zip(&port.statements) {
            compare_statement(s, t);
        }
        let mut rng = Rng(713);
        for _ in 0..2000 {
            let q = request(&mut rng);
            assert_eq!(
                upstream_identity(up, &q),
                rustfs_kernel::policies::policy_is_allowed(
                    &port.statements,
                    &kargs(&q),
                    &env(&q.conds)
                )
            );
        }
    }
    assert_eq!(
        k::default_version(),
        rustfs_policy::policy::DEFAULT_VERSION.as_bytes()
    );
    assert_eq!(
        k::kms_key_administrator(),
        u::KMS_KEY_ADMINISTRATOR.as_bytes()
    );
    assert_eq!(k::kms_key_user(), u::KMS_KEY_USER.as_bytes());
    assert_eq!(k::kms_auditor(), u::KMS_AUDITOR.as_bytes());
    assert_eq!(k::all_kms_keys(), b("*"));
    // Exercise the constructors with empty and mixed lists as well as the valid canned inputs.
    let mut rng = Rng(714);
    for _ in 0..1000 {
        let actions = (0..rng.below(8))
            .map(|_| rustfs_policy::policy::action::Action::try_from(*rng.pick(ACTIONS)).unwrap())
            .collect::<Vec<_>>();
        let up = rustfs_policy::policy::Statement {
            effect: rustfs_policy::policy::Effect::Allow,
            actions: rustfs_policy::policy::ActionSet(actions.clone()),
            resources: rustfs_policy::policy::ResourceSet(vec![
                rustfs_policy::policy::resource::Resource::Kms("*".into()),
            ]),
            ..Default::default()
        };
        compare_statement(&up, &k::kms_allow(actions.iter().map(kaction).collect()));
    }
    let up: Policy = serde_json::from_value(
        serde_json::json!({"Statement":[{"Effect":"Allow", "Action":"sts:AssumeRole"}]}),
    )
    .unwrap();
    compare_statement(&up.statements[0], &k::assume_role_allow());
}

#[test]
fn tag_and_full_evaluation_agree() {
    let mut rng = Rng(573);
    for _ in 0..10000 {
        let (up, port) = policy(&mut rng);
        let mut req = tests::request(&mut rng);
        for name in [
            "ExistingObjectTag/k0",
            "ExistingObjectTag/k1",
            "ExistingObjectTag/k2",
            "ExistingObjectTag/k3",
        ] {
            if rng.chance(80) {
                req.conds.insert(
                    name.into(),
                    vec![
                        rng.pick(&[
                            "x",
                            "",
                            "1",
                            "true",
                            "YQ==",
                            "invalid",
                            "2025-01-01T00:00:00Z",
                        ])
                        .to_string(),
                    ],
                );
            }
        }
        let kargs = tests::kargs(&req);
        let env = tests::env(&req.conds);
        let uargs = u::Args {
            account: &req.account,
            groups: &None,
            action: u::action::Action::try_from(<&str>::from(&req.action)).unwrap(),
            bucket: &req.bucket,
            object: &req.object,
            conditions: &req.conds,
            claims: &req.claims,
            is_owner: req.is_owner,
            deny_only: req.deny_only,
        };
        assert_eq!(
            k::policy_uses_existing_object_tag_conditions(&port),
            u::policy_uses_existing_object_tag_conditions(&up)
        );
        assert_eq!(
            k::policy_needs_existing_object_tag_for_args(&port, &kargs, &env),
            pollster::block_on(u::policy_needs_existing_object_tag_for_args(&up, &uargs))
        );
        assert_eq!(
            k::policy_is_allowed(&port, &kargs, &env),
            pollster::block_on(up.is_allowed(&uargs))
        );
        let mut ub = u::BucketPolicy {
            id: up.id.clone(),
            version: up.version.clone(),
            statements: vec![],
        };
        let mut kb = k::BucketPolicy {
            id: port.id.clone(),
            version: port.version.clone(),
            statements: vec![],
        };
        for (a, z) in up.statements.iter().zip(&port.statements) {
            assert_eq!(
                k::functions_use_existing_object_tag(&z.conditions),
                u::functions_use_existing_object_tag(&a.conditions)
            );
            assert_eq!(
                k::statement_is_allowed(z, &kargs, &env),
                pollster::block_on(a.is_allowed(&uargs))
            );
            let principals = if rng.chance(50) {
                vec!["*"]
            } else {
                vec!["alice"]
            };
            let principal = serde_json::from_value(serde_json::json!({"AWS":principals})).unwrap();
            ub.statements.push(u::statement::BPStatement {
                sid: a.sid.clone(),
                effect: a.effect.clone(),
                principal,
                actions: a.actions.clone(),
                not_actions: a.not_actions.clone(),
                resources: a.resources.clone(),
                not_resources: a.not_resources.clone(),
                conditions: a.conditions.clone(),
            });
            kb.statements.push(k::BPStatement {
                sid: z.sid.clone(),
                effect: z.effect,
                principal: s::Principal {
                    aws: principals.iter().map(|s| b(s)).collect(),
                    service: vec![],
                },
                actions: z.actions.clone(),
                not_actions: z.not_actions.clone(),
                resources: z.resources.clone(),
                not_resources: z.not_resources.clone(),
                conditions: z.conditions.clone(),
            });
        }
        let uba = u::BucketPolicyArgs {
            account: &req.account,
            groups: &None,
            action: uargs.action.clone(),
            bucket: &req.bucket,
            object: &req.object,
            conditions: &req.conds,
            is_owner: req.is_owner,
        };
        let kba = s::BucketPolicyArgs {
            account: kargs.account.clone(),
            action: kargs.action.clone(),
            bucket: kargs.bucket.clone(),
            object: kargs.object.clone(),
            conditions: kargs.conditions.clone(),
            is_owner: kargs.is_owner,
        };
        assert_eq!(
            crate::validation::err(k::bucket_is_valid(&kb)),
            ub.is_valid().map_err(|e| e.to_string())
        );
        assert_eq!(
            k::bucket_policy_uses_existing_object_tag_conditions(&kb),
            u::bucket_policy_uses_existing_object_tag_conditions(&ub)
        );
        assert_eq!(
            k::bucket_policy_needs_existing_object_tag_for_args(&kb, &kba),
            pollster::block_on(u::bucket_policy_needs_existing_object_tag_for_args(
                &ub, &uba
            ))
        );
        assert_eq!(
            k::bucket_policy_is_allowed(&kb, &kba, &env),
            pollster::block_on(ub.is_allowed(&uba))
        );
        for (a, z) in ub.statements.iter().zip(&kb.statements) {
            assert_eq!(
                k::bp_statement_is_allowed(z, &kba, &env),
                pollster::block_on(a.is_allowed(&uba))
            );
        }
    }
}

fn identity_cases(seed: u64, mut check: impl FnMut(&[Statement], &Args, bool) -> bool) {
    let mut r = Rng(seed);
    let mut hits = 0;
    for _ in 0..N {
        let (_, sts) = identity_policy(&mut r);
        let q = request(&mut r);
        let a = kargs(&q);
        let e = env(&q.conds);
        let allowed = policy_is_allowed(&sts, &a, &e);
        if check(&sts, &a, allowed) {
            hits += 1;
        }
    }
    assert!(hits >= MIN_HITS, "premises held {hits} times");
}

#[test]
fn identity_policies_agree() {
    let mut r = Rng(0x1D3A_77F0_0C0F_FEE1);
    let mut allowed = 0;
    let n = 400_000;
    for i in 0..n {
        let (p, sts) = identity_policy(&mut r);
        let q = request(&mut r);
        let want = upstream_identity(&p, &q);
        let got = policy_is_allowed(&sts, &kargs(&q), &env(&q.conds));
        assert_eq!(got, want, "case {i}: {}\n{:?} {} {}/{} {:?} {:?}", serde_json::to_string(&p).unwrap(),
            q.action, q.account, q.bucket, q.object, q.conds, q.claims);
        allowed += want as usize;
    }
    assert!(allowed > n / 20 && allowed < n - n / 20, "{allowed}");
}
